    @EventHandler( payloadType=CreateOrderEvent.class )
    public void handle( CreateOrderEvent event) {
	    LOGGER.info("handling CreateOrderEvent - " + event );
	    Order entity = new Order();
            entity.setOrderId( event.getOrderId() );
            entity.setOrderNumber( event.getOrderNumber() );
            entity.setPlacedDate( event.getPlacedDate() );
            entity.setSubtotal( event.getSubtotal() );
            entity.setDiscountTotal( event.getDiscountTotal() );
            entity.setShippingTotal( event.getShippingTotal() );
            entity.setTaxTotal( event.getTaxTotal() );
            entity.setGrandTotal( event.getGrandTotal() );
            entity.setShippingAddress( event.getShippingAddress() );
            entity.setBillingAddress( event.getBillingAddress() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllOrder( entity );
    }

