    /**
     * Method to retrieve the Order via an OrderPrimaryKey.
     * @param 	id Long
     * @return 	Order
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Order handle( FindOrderQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getOrderId() );
    }
    
    /**
     * Method to retrieve a collection of all Orders
     *
     * @param	query	FindAllOrderQuery 
     * @return 	List<Order> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Order> handle( FindAllOrderQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindOrder,
 * but only if the id matches
 *
 * @param		entity	Order
 */
	protected void emitFindOrder( Order entity ) {
		LOGGER.info("handling emitFindOrder" );
		
	    queryUpdateEmitter.emit(FindOrderQuery.class,
	                            query -> query.getFilter().getOrderId().equals(entity.getOrderId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllOrder
	 * 
	 * @param		entity	Order
	 */
	protected void emitFindAllOrder( Order entity ) {
		LOGGER.info("handling emitFindAllOrder" );
		
	    queryUpdateEmitter.emit(FindAllOrderQuery.class,
	                            query -> true,
	                            entity);
	}

